<template>
  <div id="app">
    <router-view />
  </div>
</template>

<script>
export default {
  name: "App",
  data() {
    return {
      style: {
        width: 1920,
        height: 1080,
      },
      pageW: null,
      pageH: null,
    };
  },
  //可选的页面宽度// 可选的页面高度
  methods: {
    getScale() {
      //如果pageW/pageH 有值，则使用它们作为参考尺寸，否则使用window 的尺寸
      const w = this.pageW
        ? this.pageW / this.style.width
        : window.screen.width / this.style.width;
      const h = this.pageH
        ? this.pageH / this.style.height
        : window.screen.height / this.style.height;
      return { x: w, y: h };
    },
    setScale() {
      const scale = this.getScale();

      document.body.style.width = this.style.width + "px";
      document.body.style.height = this.style.height + "px";

      document.body.style.transform = `scale(${scale.x}, ${scale.y})`;
      document.body.style[
        "-webkit-transform"
      ] = `scale(${scale.x}, ${scale.y})`;

      this.$store.commit("CALC_HEIGHT", scale.y)

      document.body.style.transformOrigin = "0 0";
      document.body.style["-webkit-transform-origin"] = "0 0";
      //防止页面滚动
      document.body.style.overflow = "hidden";
    },
  },
  mounted() {
    //初始化时获取一次缩放比例
    this.setScale();
    //监听窗口大小变化
    window.addEventListener("resize", this.setScale);
  },
  beforeDestroy() {
    //移除窗口大小变化监听
    window.removeEventListener("resize", this.setScale);
  },
};
</script>

